{
  "compilerOptions": {
    "target": "es2020",
    "jsx": "react-jsx",
    "module": "ES2022",
    "moduleResolution": "node",
    "noEmit": true,
    "isolatedModules": true,
    "moduleDetection": "force",
    "esModuleInterop": true,
    "forceConsistentCasingInFileNames": true,
    "strict": true,
    "skipLibCheck": true,
    "paths": {
      "fake-external-lib": [
        "./src/fake-external-lib/index"
      ],
      "fake-external-component": [
        "./src/fake-external-lib/component"
      ]
    }
  },
  "include": [
    "src"
  ]
}

export type Expect<T extends true> = T;
export type ExpectTrue<T extends true> = T;
export type ExpectFalse<T extends false> = T;
export type IsTrue<T extends true> = T;
export type IsFalse<T extends false> = T;

export type Equal<X, Y> = (<T>() => T extends X ? 1 : 2) extends <
  T,
>() => T extends Y ? 1 : 2
  ? true
  : false;
export type NotEqual<X, Y> = true extends Equal<X, Y> ? false : true;

// https://stackoverflow.com/questions/49927523/disallow-call-with-any/49928360#49928360
export type IsAny<T> = 0 extends 1 & T ? true : false;
export type NotAny<T> = true extends IsAny<T> ? false : true;

export type Debug<T> = { [K in keyof T]: T[K] };
export type MergeInsertions<T> = T extends object
  ? { [K in keyof T]: MergeInsertions<T[K]> }
  : T;

export type Alike<X, Y> = Equal<MergeInsertions<X>, MergeInsertions<Y>>;

/**
 * Expect that one type is assignable to another.
 *
 * @example
 *
 * type tests = [
 *   // Expect that `number` is assignable to `1`.
 *   Expect<Extends<1, number>>,
 *   // Expect that `abc` is assignable to `string`
 *   Expect<Extends<'abc', string>>,
 * ];
 */
export type Extends<VALUE, EXPECTED> = EXPECTED extends VALUE ? true : false;
export type ExpectValidArgs<
  FUNC extends (...args: any[]) => any,
  ARGS extends any[],
> = ARGS extends Parameters<FUNC> ? true : false;

export type UnionToIntersection<U> = (
  U extends any ? (k: U) => void : never
) extends (k: infer I) => void
  ? I
  : never;

/**
 * A fake function to create a user
 */
export const createUser = (
  user: {
    name: string;
    email: string;
  },
  opts?: {
    throwOnError?: boolean;
  },
): Promise<{
  id: string;
  name: string;
  email: string;
}> => {
  return fetch("/user", {
    method: "POST",
    body: JSON.stringify(user),
  }).then((response) => response.json());
};

/**
 * A fake auth token hook.
 */
export const useAuthToken = () => {
  return "123";
};

/**
 * A fake video fetcher.
 */
export const fetchVideo = (src: string) => {
  return fetch(src).then((response) => response.blob());
};

/**
 * A fake video appender.
 */
export const appendVideoToDomAndPlay = (blob: Blob) => {
  const video = document.createElement("video");
  video.src = URL.createObjectURL(blob);
  video.play();
};

/**
 * A fake router interface
 */
export interface Router {
  push: (path: string) => void;
}

/**
 * A fake useRouter hook
 */
export const useRouter = () => {
  return {
    push: (path: string) => {
      console.log(`Navigating to ${path}`);
    },
  };
};

const MyComponent = (props: { id: string }) => {
  return <div>Hello!</div>;
};

export default MyComponent;
